import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.Dg5fKO7V.js";const u=JSON.parse('{"title":"Coverage","description":"","frontmatter":{},"headers":[],"relativePath":"coverage.md","filePath":"coverage.md","lastUpdated":1788563284000}'),s={name:"coverage.md"};function i(n,e,d,c,l,h){return a(),r("div",null,[...e[0]||(e[0]=[o(`<h1 id="coverage" tabindex="-1">Coverage <a class="header-anchor" href="#coverage" aria-label="Permalink to &quot;Coverage&quot;">​</a></h1><p>Coverage is generated in the application checkout and evaluated by Sonar. Run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:coverage:frontend</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:coverage:rust</span></span></code></pre></div><p>The frontend command prints a summary, writes a browsable report to <code>coverage/index.html</code> and writes <code>coverage/lcov.info</code>. The Rust command runs the library suite through <code>cargo llvm-cov</code> and writes <code>coverage/rust-lcov.info</code>. <code>npm run sonar</code> regenerates both reports before every scan. The documentation build does not generate or publish a fresh application report of its own.</p><h2 id="what-is-measured" tabindex="-1">What is measured <a class="header-anchor" href="#what-is-measured" aria-label="Permalink to &quot;What is measured&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Suite</th><th>Runner</th><th>What it covers</th></tr></thead><tbody><tr><td>Frontend</td><td>Vitest with the V8 provider</td><td>Product TypeScript and TSX under <code>src/</code></td></tr><tr><td>Rust</td><td><code>cargo llvm-cov --lib</code></td><td>Product Rust under <code>src-tauri/src/</code>; ignored live probes stay outside the deterministic report</td></tr><tr><td>Project scripts and Sonar tooling</td><td>Excluded</td><td>Commands are analyzed for quality but are not browser application code</td></tr><tr><td>Locales, declarations, tests and <code>src/app/main.tsx</code></td><td>Excluded</td><td>Static tables, harness code and the application entry point do not describe executable product branches</td></tr></tbody></table><p>Install the report tool once with <code>cargo install cargo-llvm-cov --locked</code>. Windows paths are remapped by the committed command so the Linux scanner container resolves them to the same Rust sources.</p><h2 id="reading-it" tabindex="-1">Reading it <a class="header-anchor" href="#reading-it" aria-label="Permalink to &quot;Reading it&quot;">​</a></h2><p>A file with no coverage is not automatically a problem, and a file with full coverage is not automatically correct. The report is most useful for finding untested decisions and error paths.</p><p>Vitest and cargo-llvm-cov do not reject a percentage themselves. The frontend Sonar gate requires 80% coverage; the backend gate requires 60% coverage of deterministic domain logic. Tauri, OS, external-process and live-provider adapters stay statically analyzed but are excluded from the offline backend coverage denominator. See <a href="./SonarQube">SonarQube</a> for the exact workflow.</p><p>Architecture, documentation, locale and asset invariants are not measured as executable tests. They are project-specific Sonar issues, described under <a href="/AniSphere.docs/Architecture-Boundaries">Architecture boundaries</a> and <a href="/AniSphere.docs/Testing">Testing</a>.</p>`,11)])])}const g=t(s,[["render",i]]);export{u as __pageData,g as default};
